import { useState, useRef, useEffect } from 'react';
import { Check, Package, ShoppingCart } from 'lucide-react';

export default function AmazonOTPVerification() {
  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const [showSuccess, setShowSuccess] = useState(false);
  const [isVerifying, setIsVerifying] = useState(false);
  const inputRefs = useRef([]);

  const handleChange = (index, value) => {
    if (value.length > 1) {
      value = value.slice(0, 1);
    }

    if (!/^\d*$/.test(value)) return;

    const newOtp = [...otp];
    newOtp[index] = value;
    setOtp(newOtp);

    if (value !== '' && index < 5) {
      inputRefs.current[index + 1]?.focus();
    }
  };

  const handleKeyDown = (index, e) => {
    if (e.key === 'Backspace' && otp[index] === '' && index > 0) {
      inputRefs.current[index - 1]?.focus();
    }
  };

  const handlePaste = (e) => {
    e.preventDefault();
    const pastedData = e.clipboardData.getData('text').slice(0, 6);
    if (!/^\d+$/.test(pastedData)) return;

    const newOtp = [...otp];
    pastedData.split('').forEach((char, index) => {
      if (index < 6) {
        newOtp[index] = char;
      }
    });
    setOtp(newOtp);

    const nextEmptyIndex = newOtp.findIndex(val => val === '');
    if (nextEmptyIndex !== -1) {
      inputRefs.current[nextEmptyIndex]?.focus();
    } else {
      inputRefs.current[5]?.focus();
    }
  };

  const handleVerify = () => {
    const otpValue = otp.join('');
    if (otpValue.length === 6) {
      setIsVerifying(true);
      setTimeout(() => {
        setIsVerifying(false);
        setShowSuccess(true);
      }, 1000);
    }
  };

  const handleCloseSuccess = () => {
    setShowSuccess(false);
    setOtp(['', '', '', '', '', '']);
    inputRefs.current[0]?.focus();
  };

  useEffect(() => {
    inputRefs.current[0]?.focus();
  }, []);

  const isOtpComplete = otp.every(digit => digit !== '');

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        {/* Header */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center gap-2 mb-4">
            <ShoppingCart className="w-10 h-10 text-orange-500" />
            <h1 className="text-3xl font-bold text-slate-800">amazon</h1>
          </div>
          <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
            <Package className="w-16 h-16 text-orange-500 mx-auto mb-3" />
            <h2 className="text-xl font-semibold text-slate-800 mb-2">
              Verify Your Order
            </h2>
            <p className="text-slate-600 text-sm">
              Enter the 6-digit verification code to confirm your delivery
            </p>
          </div>
        </div>

        {/* OTP Input Card */}
        <div className="bg-white rounded-lg shadow-lg p-8">
          <div className="flex justify-center gap-3 mb-6">
            {otp.map((digit, index) => (
              <input
                key={index}
                ref={el => inputRefs.current[index] = el}
                type="text"
                inputMode="numeric"
                maxLength={1}
                value={digit}
                onChange={(e) => handleChange(index, e.target.value)}
                onKeyDown={(e) => handleKeyDown(index, e)}
                onPaste={index === 0 ? handlePaste : undefined}
                className="w-12 h-14 text-center text-2xl font-bold border-2 border-slate-300 rounded-lg focus:border-orange-500 focus:outline-none focus:ring-2 focus:ring-orange-200 transition-all"
              />
            ))}
          </div>

          <button
            onClick={handleVerify}
            disabled={!isOtpComplete || isVerifying}
            className={`w-full py-3 rounded-lg font-semibold text-white transition-all ${
              isOtpComplete && !isVerifying
                ? 'bg-gradient-to-r from-orange-400 to-orange-500 hover:from-orange-500 hover:to-orange-600 shadow-md hover:shadow-lg'
                : 'bg-slate-300 cursor-not-allowed'
            }`}
          >
            {isVerifying ? (
              <span className="flex items-center justify-center gap-2">
                <svg className="animate-spin h-5 w-5" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none" />
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
                </svg>
                Verifying...
              </span>
            ) : (
              'Verify & Confirm Delivery'
            )}
          </button>

          <div className="mt-4 text-center">
            <button className="text-sm text-orange-600 hover:text-orange-700 font-medium">
              Resend Code
            </button>
          </div>
        </div>

        <p className="text-center text-xs text-slate-500 mt-4">
          Secure verification powered by Amazon
        </p>
      </div>

      {/* Success Modal */}
      {showSuccess && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-8 transform animate-[scale-in_0.3s_ease-out]">
            <div className="text-center">
              <div className="mx-auto w-20 h-20 bg-gradient-to-br from-green-400 to-green-500 rounded-full flex items-center justify-center mb-6 shadow-lg">
                <Check className="w-12 h-12 text-white animate-[check-pop_0.5s_ease-out]" />
              </div>

              <h3 className="text-2xl font-bold text-slate-800 mb-2">
                Order Delivered Successfully!
              </h3>

              <p className="text-slate-600 mb-2">
                Your order has been confirmed and delivered
              </p>

              <div className="bg-green-50 border border-green-200 rounded-lg p-4 mb-6">
                <p className="text-sm text-green-800 font-medium">
                  OTP: {otp.join('')}
                </p>
                <p className="text-xs text-green-600 mt-1">
                  Verified successfully ✓
                </p>
              </div>

              <button
                onClick={handleCloseSuccess}
                className="w-full bg-gradient-to-r from-orange-400 to-orange-500 hover:from-orange-500 hover:to-orange-600 text-white font-semibold py-3 rounded-lg transition-all shadow-md hover:shadow-lg"
              >
                Continue Shopping
              </button>
            </div>
          </div>
        </div>
      )}

      <style jsx>{`
        @keyframes scale-in {
          from {
            transform: scale(0.9);
            opacity: 0;
          }
          to {
            transform: scale(1);
            opacity: 1;
          }
        }

        @keyframes check-pop {
          0%, 100% {
            transform: scale(1);
          }
          50% {
            transform: scale(1.2);
          }
        }
      `}</style>
    </div>
  );
}
